<div class="row g-4"><div class="col-lg-8"><img class="detail-image" src="<?= baseUrl('images/uploads/'.e($photo['file_name'])) ?>" alt="<?= e($photo['title']) ?>"></div><div class="col-lg-4"><div class="eyebrow">Photo detail</div><h1 class="h2 fw-bold mt-2"><?= e($photo['title']) ?></h1><p class="text-secondary">By <?= e($photo['author']) ?> · <?= e($photo['date_time']) ?></p><p><?= nl2br(e($photo['description']??'')) ?></p><?php if(currentUser() && (int)currentUser()['id']===(int)$photo['user_id']): ?><form method="post" action="<?= baseUrl('photo/'.$photo['id'].'/delete') ?>" onsubmit="return confirm('Delete this photo permanently?')"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><button class="btn btn-outline-danger btn-sm">Delete my photo</button></form><?php endif; ?></div></div><section class="row justify-content-center mt-5"><div class="col-lg-8"><h2 class="h4">Comments <span class="text-secondary">(<?= count($comments) ?>)</span></h2><?php foreach($comments as $comment): ?><div class="border-bottom py-3"><div class="fw-bold"><?= e($comment['author']) ?> <span class="fw-normal text-secondary small">· <?= e($comment['date_time']) ?></span></div><div><?= nl2br(e($comment['comment'])) ?></div></div><?php endforeach; ?><?php if(currentUser()): ?><form class="mt-4" method="post" action="<?= baseUrl('photo/'.$photo['id'].'/comment') ?>"><input type="hidden" name="csrf" value="<?= csrfToken() ?>"><label class="form-label fw-bold">Add a comment</label><textarea class="form-control mb-2" name="comment" maxlength="1000" required rows="3"></textarea><button class="btn btn-dark">Post comment</button></form><?php else: ?><p class="text-secondary mt-4"><a href="<?= baseUrl('login') ?>">Sign in</a> to join the conversation.</p><?php endif; ?></div></section>
